// Section XIX.C.4 - Experiment Review
// Tracks active experiments, hypothesis status, results

const experiments = [
  {
    id: 'pain-first-templates',
    hypothesis: 'Pain-first outreach templates (leading with prospect pain instead of product vision) will increase response rate above the 0.67% baseline for cold email',
    start_date: '2026-03-21',
    status: 'active',
    target_segment: 'All CRM lanes (buyer, builder, investor, connector)',
    success_criteria: 'Response rate > 2% on first 50 sends',
    failure_criteria: 'No improvement after 50 sends',
    current_sends: 0,
    current_responses: 0,
    learning_objective: 'Does pain-first messaging outperform vision-first for cold outreach?',
    next_iteration: 'If fails: try shorter messages (under 80 words); if wins: expand to all 365 contacts'
  },
  {
    id: 'counterpart-scoring',
    hypothesis: 'Scoring prospects on 7-factor counterpart model will surface 2-3 true counterparts from the 5 hypotheses (APCO, FTI, Weber, FGS, Brunswick)',
    start_date: '2026-03-21',
    status: 'active',
    target_segment: 'Known counterpart hypotheses + similar firms in CRM',
    success_criteria: 'At least 1 true counterpart (>75% score) initiates conversation',
    failure_criteria: 'All 5 hypotheses score below 55% (no plausible partners)',
    current_sends: 0,
    current_responses: 0,
    learning_objective: 'Which counterpart type scores highest on 7-factor model?',
    next_iteration: 'If fails: revise scoring weights; if wins: expand outreach to top-scored firms'
  },
  {
    id: 'warm-intro-priority',
    hypothesis: 'Prioritizing warm intros (40% baseline response) over cold outreach will produce 3x more meetings in 30 days',
    start_date: '2026-03-21',
    status: 'active',
    target_segment: 'Contacts with mutual connections or warm signals',
    success_criteria: '3+ meetings booked in 30 days via warm intros only',
    failure_criteria: 'Under 1 meeting after 30 days',
    current_meets: 0,
    learning_objective: 'Can warm intro pipeline alone drive first revenue?',
    next_iteration: 'Map all warm intro paths from 365 contacts'
  }
];

// Calculate days running for each
const today = new Date();
experiments.forEach(e => {
  const start = new Date(e.start_date);
  e.days_running = Math.floor((today - start) / (24*60*60*1000));
});

const summary = {
  active_experiments: experiments.filter(e => e.status === 'active').length,
  experiments: experiments,
  last_checked: today.toISOString()
};

return [{ json: summary }];

